select case when d.budget >= 3527000 then 'high' when d.budget >= 861000 then 'mid' else 'low' end as budget_bucket, max(e.salary) as max_salary from employees e inner join departments d on e.dept_id = d.id where d.dept_name not in ('Engineering', 'Legal', 'Sales') group by case when d.budget >= 3527000 then 'high' when d.budget >= 861000 then 'mid' else 'low' end order by max_salary, budget_bucket;
